structureCode.vanilla:
const campo = createTextarea({
  id: 'description',
  placeholder: 'ex: Descreva o produto...',
  class: 'nds-resize-y nds-min-h-30',
});
campo.maxLength = 500;

const contador = document.createElement('span');
contador.className = 'nds-text-caption nds-text-muted-foreground';
contador.setAttribute('aria-live', 'polite');
contador.textContent = '0/500';
campo.addEventListener('input', () => {
  contador.textContent = campo.value.length + '/500';
});

extensibilityCode.react:
// Contador de caracteres acessível
const [value, setValue] = useState('');
const max = 500;

<div className="nds-stack" data-spacing="sm">
  <Label htmlFor="description">Descrição</Label>
  <Textarea
    id="description"
    value={value}
    onChange={(e) => setValue(e.target.value)}
    placeholder="ex: Descreva o produto..."
    className="nds-resize-y nds-min-h-30"
    maxLength={max}
  />
  <div className="nds-cluster nds-text-caption nds-text-muted-foreground" data-justify="between">
    <span>Descreva com clareza.</span>
    <span aria-live="polite" aria-label={`${value.length} de ${max} caracteres usados`}>
      {value.length}/{max}
    </span>
  </div>
</div>

extensibilityCode.vanilla:
// Contador de caracteres acessível
const max = 500;
const campo = createTextarea({
  id: 'description',
  placeholder: 'ex: Descreva o produto...',
  class: 'nds-resize-y nds-min-h-30',
});
campo.maxLength = max;

const contador = document.createElement('span');
contador.className = 'nds-text-caption nds-text-muted-foreground nds-tabular-nums';
contador.setAttribute('aria-live', 'polite');

const atualizar = () => {
  const n = campo.value.length;
  contador.textContent = n + '/' + max;
  contador.setAttribute('aria-label', n + ' de ' + max + ' caracteres usados');
};
campo.addEventListener('input', atualizar);
atualizar();

customizationCode.web:
/* Campo mais alto que os 64px de origem */
.nds-textarea {
  min-height: 11.25rem;   /* 180px */
}

/* Anel de foco na cor da marca */
.nds-textarea:focus-visible {
  border-color: hsl(var(--primary));
  box-shadow: 0 0 0 2px hsl(var(--primary) / 0.3);
}

